const MonoIcon& SplitChevron(ButtonSize size, bool up) {
  switch (size) {
    case ButtonSize::kExtraSmall:
      return up ? chevron_22_up() : chevron_22_down();
    case ButtonSize::kSmall:
      return up ? chevron_22_up() : chevron_22_down();
    case ButtonSize::kMedium:
      return up ? chevron_26_up() : chevron_26_down();
    case ButtonSize::kLarge:
      return up ? chevron_38_up() : chevron_38_down();
    case ButtonSize::kExtraLarge:
      return up ? chevron_50_up() : chevron_50_down();
  }
  return chevron_22_down();
}
